"""Prepare a minimal patch against an actively edited daemon; never edit it.

Use git apply --check and explicit file-owner review before applying the patch.
The old direct SQL path bypasses per-mission lease and independent QA.
"""

from __future__ import annotations

import argparse
import difflib
from pathlib import Path

START = "        # BELGE YOLU: proje bağlı olmayan departmanların bekleyen görevleri"
END = "        # SÜREKLİ ÖĞRENME: boştaki çalışanlar"
REPLACEMENT = (
    "        # Unverified direct document completion is disabled.\n"
    "        # Documents may be generated by owner_console._execute, which\n"
    "        # routes work through the leased worker and independent QA stages.\n"
    "        # Never UPDATE missions.status='completed' outside the queue API.\n"
)


def safe_daemon_text(original: str) -> str:
    if original.count(START) != 1 or original.count(END) != 1:
        raise ValueError("expected unsafe document path markers not found exactly once")
    head, rest = original.split(START, 1)
    _, tail = rest.split(END, 1)
    if "update missions set status='completed'" not in rest.split(END, 1)[0].lower():
        raise ValueError("unsafe completion SQL not found inside expected block")
    return head + REPLACEMENT + END + tail


def build_diff(original: str) -> str:
    proposed = safe_daemon_text(original)
    return "".join(difflib.unified_diff(
        original.splitlines(keepends=True),
        proposed.splitlines(keepends=True),
        fromfile="a/ahos_core/ahos/daemon.py",
        tofile="b/ahos_core/ahos/daemon.py",
        n=3,
    ))


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Create read-only daemon hotfix patch")
    parser.add_argument("--source", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args(argv)
    source = Path(args.source)
    patch = build_diff(source.read_text(encoding="utf-8"))
    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(patch, encoding="utf-8")
    print(f"PATCH_READY size_bytes={len(patch.encode('utf-8'))}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
